fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    for (i, &value) in nums.iter().enumerate() {
        if value == target {
            // Safe to cast because nums.len() < i32::MAX by problem assumption
            return i as i32;
        }
    }
    -1
}

fn main() {
    let tests = vec![
        (vec![], 10, -1),
        (vec![1, 2, 3, 4, 5], 3, 2),
        (vec![5, 4, 3, 2, 1], 5, 0),
        (vec![1, 2, 3, 2, 1], 2, 1),
        (vec![10, 20, 30], 40, -1),
    ];

    for (nums, target, expected) in tests {
        let result = linear_search(nums.clone(), target);
        println!(
            "Searching for {} in {:?}: got {}, expected {}",
            target, nums, result, expected
        );
        assert_eq!(result, expected);
    }
}